  {"name": "AlgebraicGeometry.isProper_eq", "module": "Mathlib.AlgebraicGeometry.Morphisms.Proper", "type": ": @IsProper = (@IsSeparated ⊓ @UniversallyClosed : MorphismProperty Scheme) ⊓ @LocallyOfFiniteType", "doc": "A morphism of schemes is proper if and only if it is separated, universally closed, and locally of finite type."}
  {"name": "AlgebraicGeometry.IsProper", "module": "Mathlib.AlgebraicGeometry.Morphisms.Proper", "type": "{X Y : AlgebraicGeometry.Scheme} → (X ⟶ Y) → Prop", "doc": "A morphism $ f: X \\to Y $ of schemes is proper."}
  {"name": "AlgebraicGeometry.IsProper.instOfIsFinite", "module": "Mathlib.AlgebraicGeometry.Morphisms.Proper", "type": "[IsFinite f] : IsProper f", "doc": "Every finite morphism of schemes is a proper morphism."}
  {"name": "AlgebraicGeometry.Scheme.Hom.isProperMap", "module": "Mathlib.AlgebraicGeometry.Morphisms.UniversallyClosed", "type": "(f : X ⟶ Y) [UniversallyClosed f] : IsProperMap f", "doc": "If $ f: X \\to Y $ is a morphism of schemes that is universally closed, then $ f $ is a proper map, meaning that the preimage of every compact subset of $ Y $ is compact in $ X $."}
